import { CAR_DATABASE, getOJKRate, STAMP_DUTY, INSURANCE_PROVIDERS, EXPANSION_RATES, PLATE_REGIONS } from '../constants';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface CarWizardProps {
  onBack: () => void;
}

const CarWizard: React.FC<CarWizardProps> = ({ onBack }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [v, setV] = useState<VehicleState>({
    isOthers: false, brand: '', model: '', year: 2024, price: 0, priceBase: 0,
    plateRegion: '2', plateCode: '', plateNumber: '', plateSuffix: '',
    usage: 'PRIBADI', condition: 'BARU', insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: false, tpl: 0 },
    promoCode: '', discountValue: 0, discountType: 'PERCENT', selectedProvider: null
  });
  const [customer, setCustomer] = useState<CustomerData>({ name: '', ktpNumber: '', address: '', email: '', phone: '', city: '' });
  const [photos, setPhotos] = useState<Record<string, string>>({});
  const [score, setScore] = useState<VerificationScore | null>(null);
  const [sortMode, setSortMode] = useState<'price' | 'rating' | 'coins'>('price');

  useEffect(() => {
    if (v.plateCode) {
      const reg = PLATE_REGIONS[v.plateCode] || '3';
      setV(prev => ({ ...prev, plateRegion: reg }));
    }
  }, [v.plateCode]);

  const calculateTotal = (prov: Provider) => {
    const priceM = v.price / 1_000_000;
    let rate = getOJKRate(priceM, v.plateRegion, v.insuranceType);

    let expPremium = 0;
    if (v.expansions.flood) expPremium += v.price * EXPANSION_RATES.FLOOD / 100;
    if (v.expansions.earthquake) expPremium += v.price * EXPANSION_RATES.EARTHQUAKE / 100;
    if (v.expansions.srcc) expPremium += v.price * (v.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : (EXPANSION_RATES.SRCC as any).TLO) / 100;
    if (v.expansions.terrorism) expPremium += v.price * (v.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : (EXPANSION_RATES.TERRORISM as any).TLO) / 100;

    if (v.expansions.authorizedWorkshop) rate += (EXPANSION_RATES as any).AUTHORIZED_WORKSHOP || 0.2;

    const basePremium = v.price * rate / 100;
    const totalPremium = basePremium + expPremium;

    let disc = v.discountType === 'PERCENT' ? (totalPremium * v.discountValue / 100) : v.discountValue;
    disc = Math.min(disc, totalPremium * 0.25);

    return {
      base: basePremium,
      expansion: expPremium,
      discount: disc,
      final: totalPremium - disc + prov.adminFee + STAMP_DUTY,
      commission: (totalPremium - disc) * 0.25,
      coins: (totalPremium - disc) * prov.pathCoins / 100
    };
  };

  const handleKTPUpload = async (file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const data = await analyzeKTP(base64);
      if (data) setCustomer(prev => ({ ...prev, ...data }));
      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const handleSTNKUpload = async (file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const data = await analyzeSTNK(base64);
