      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const handleSurvey = async () => {
    setLoading(true);
    const surveyImages = (Object.entries(photos) as [string, string][]).map(([label, base64]) => ({ label, base64 }));
    const res = await analyzeVehicleVerification(surveyImages);
