              <input placeholder="8888" maxLength={4} className="flex-1 p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white text-center font-black" value={v.plateNumber} onChange={e => setV({...v, plateNumber: e.target.value})} />
