import { GoogleGenAI } from "@google/genai";

export interface ClaimPart {
  partName: string;
  damageType: string;
  severity: number; // 0-100
  action: 'Repair' | 'Replace';
  estimatedCost: number;
  technicalNote: string;
}

export interface ClaimAnalysisData {
  claimId: string;
  timestamp: string;
  overallSeverity: 'Low' | 'Medium' | 'High' | 'Total Loss';
  totalEstimation: number;
  itemizedParts: ClaimPart[];
  fraudScore: number; // 0-100 (low is better)
  integrityCheck: {
    metadataMatch: boolean;
    lightingConsistency: boolean;
    pixelAnomaly: string;
  };
  surveyorInsight: string;
  recommendedWorkshopType: 'General' | 'Authorized' | 'Specialist';
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Act as a Senior Automotive Claim Surveyor. Analyze this vehicle damage photo with extreme technical precision.
  Provide a professional survey report in JSON format:
  {
    "claimId": "SP-XXXX",
    "timestamp": "ISO-STRING",
    "overallSeverity": "Low" | "Medium" | "High" | "Total Loss",
    "totalEstimation": number,
    "itemizedParts": [
      {
        "partName": "string (e.g., Front Bumper, Quarter Panel)",
        "damageType": "string (e.g., Dent, Scratch, Puncture, Deformation)",
        "severity": number (0-100),
        "action": "Repair" | "Replace",
        "estimatedCost": number,
        "technicalNote": "Professional explanation of the structural impact"
      }
    ],
    "fraudScore": number (0-100 where >70 is suspicious),
    "integrityCheck": {
      "metadataMatch": true,
      "lightingConsistency": true,
      "pixelAnomaly": "none or description"
    },
    "surveyorInsight": "Final executive summary for the insurance adjuster",
    "recommendedWorkshopType": "General" | "Authorized" | "Specialist"
  }

  Instructions:
  - Be realistic with Indonesian market repair costs.
  - Detect if the image looks like a re-photo of a screen (fraud).
  - Use technical automotive terminology.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.2 // Lower temperature for more consistent technical analysis
      }
    });

    const rawText = response.text;
    const parsedData = JSON.parse(rawText);
    return { success: true, data: parsedData };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return { success: false, error: "Neural Analysis Engine failed to process image." };
  }
};

