  };
  surveyorInsight: string;
  recommendedWorkshopType: 'General' | 'Authorized' | 'Specialist';
}

/**
 * Professional Claim Analysis
 */
export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Act as a Senior Automotive Claim Surveyor. Analyze this vehicle damage photo with extreme technical precision.
  Provide a professional survey report in JSON format:
  {
    "claimId": "SP-CL-AUTO-2025",
    "timestamp": "2025-05-20T10:00:00Z",
    "overallSeverity": "Low" | "Medium" | "High" | "Total Loss",
    "totalEstimation": number,
    "itemizedParts": [
      {
        "partName": "string (e.g., Front Bumper, Quarter Panel, Headlamp Assembly)",
        "damageType": "string (e.g., Dent, Scratch, Puncture, Deformation, Structural Tear)",
        "severity": number (0-100),
        "action": "Repair" | "Replace",
        "estimatedCost": number,
        "technicalNote": "Professional explanation of the structural impact"
      }
    ],
    "fraudScore": number (0-100 where >70 is suspicious),
    "integrityCheck": {
      "metadataMatch": true,
      "lightingConsistency": true,
      "pixelAnomaly": "none or description"
    },
    "surveyorInsight": "Final executive summary for the insurance adjuster including structural integrity warnings.",
    "recommendedWorkshopType": "General" | "Authorized" | "Specialist"
  }

  Instructions:
  - Be realistic with Indonesian market repair costs (IDR).
  - Detect if the image looks like a re-photo of a screen (fraud).
  - Use technical automotive terminology.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.1 
      }
    });

    return { success: true, data: JSON.parse(response.text) };
  } catch (error) {
    console.error("Gemini Claim Error:", error);
    return { success: false, error: "Neural Analysis Engine failure." };
  }
};

