const CarWizard: React.FC<CarWizardProps> = ({ onBack }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [v, setV] = useState<any>({
    isOthers: false, brand: '', model: '', year: 2024, price: 0,
    plateRegion: '2', plateCode: '', plateNumber: '', plateSuffix: '',
    usage: 'PRIBADI', insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: false },
    selectedProvider: null
  });
  const [customer, setCustomer] = useState<any>({ name: '', ktpNumber: '', email: '', phone: '' });
  const [photos, setPhotos] = useState<Record<string, string>>({});
  const [score, setScore] = useState<any>(null);

  const calculateTotal = (prov: Provider) => {
    const priceM = v.price / 1_000_000;
    let rate = getOJKRate(priceM, v.plateRegion as any, v.insuranceType);

    let expPremium = 0;
    if (v.expansions.flood) expPremium += v.price * EXPANSION_RATES.FLOOD / 100;
    if (v.expansions.earthquake) expPremium += v.price * EXPANSION_RATES.EARTHQUAKE / 100;

    const basePremium = v.price * rate / 100;
    const totalPremium = basePremium + expPremium;

    return {
      base: basePremium,
      expansion: expPremium,
      final: totalPremium + prov.adminFee + STAMP_DUTY,
      commission: totalPremium * 0.25,
      coins: totalPremium * 0.05
    };
  };

  const handleKTPUpload = async (file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const data = await analyzeKTP(base64);
      if (data) setCustomer((prev: any) => ({ ...prev, ...data }));
      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const handleSurvey = async () => {
    setLoading(true);
    const surveyImages = Object.entries(photos).map(([label, base64]) => ({ label, base64 }));
    const res = await analyzeVehicleVerification(surveyImages);
    setScore(res);
    setLoading(false);
  };

  return (
    <div className="p-6 max-w-2xl mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-10">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-3 glass-card rounded-xl text-gray-500 hover:text-primary-500 transition-all">
          <ChevronLeft size={20}/>
        </button>
        <div className="flex-1">
          <h2 className="text-2xl font-black uppercase dark:text-white tracking-tighter">Car <span className="text-primary-500">Wizard</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-2 rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 transition-all duration-500" style={{ width: `${(step/8)*100}%` }}></div>
          </div>
        </div>
      </div>

      {step === 1 && (
        <div className="space-y-6">
          <div className="grid gap-4">
            <input placeholder="Brand" className="w-full p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white" value={v.brand} onChange={e => setV({...v, brand: e.target.value.toUpperCase()})} />
            <input placeholder="Model" className="w-full p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white" value={v.model} onChange={e => setV({...v, model: e.target.value.toUpperCase()})} />
            <div className="flex gap-4">
              <input type="number" placeholder="Year" className="w-1/3 p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white" value={v.year} onChange={e => setV({...v, year: parseInt(e.target.value)})} />
              <input type="number" placeholder="Value (IDR)" className="flex-1 p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white font-black text-primary-500" value={v.price} onChange={e => setV({...v, price: parseInt(e.target.value)})} />
            </div>
          </div>
          <button onClick={() => setStep(2)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-sm shadow-xl">Next: Coverage</button>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-6">
          <div className="grid gap-4">
            {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(t => (
              <button key={t} onClick={() => setV({...v, insuranceType: t})} className={`p-8 glass-card rounded-[3rem] border-2 text-left transition-all ${v.insuranceType === t ? 'border-primary-500 bg-primary-500/5' : 'border-transparent'}`}>
                <p className="font-black dark:text-white uppercase text-xl">{t}</p>
                <p className="text-[0.6rem] text-gray-500 font-bold uppercase mt-1">Full Neural Protection</p>
              </button>
            ))}
          </div>
          <button onClick={() => setStep(3)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-sm">Find Providers</button>
        </div>
      )}

      {step === 3 && (
        <div className="grid gap-6">
          {INSURANCE_PROVIDERS.map(prov => {
            const calc = calculateTotal(prov);
            return (
              <button 
                key={prov.id} 
                onClick={() => { setV({...v, selectedProvider: prov}); setStep(4); }}
                className="p-8 glass-card rounded-[3.5rem] border border-black/5 dark:border-white/5 text-left group hover:border-primary-500 transition-all shadow-md"
              >
                <div className="flex justify-between items-center mb-4">
                  <p className="font-black text-xl dark:text-white uppercase">{prov.name}</p>
                  <p className="text-2xl font-black text-primary-500">{formatIDR(calc.final)}</p>
                </div>
                <div className="flex gap-2">
                   {prov.features.slice(0,2).map(f => <span key={f} className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest border px-2 py-1 rounded-full">{f}</span>)}
                </div>
              </button>
            );
          })}
        </div>
      )}

      {step === 4 && (
        <div className="space-y-6">
          <div className="p-16 glass-card rounded-[4rem] border-2 border-dashed border-primary-500/20 text-center relative overflow-hidden group">
             {loading ? <Loader2 className="animate-spin text-primary-500 mx-auto" size={48}/> : (
               <>
                 <ScanFace size={64} className="text-primary-500 mx-auto mb-6" />
                 <h3 className="font-black dark:text-white uppercase text-lg">Upload Identity (KTP)</h3>
                 <input type="file" accept="image/*" onChange={e => e.target.files && handleKTPUpload(e.target.files[0])} className="absolute inset-0 opacity-0 cursor-pointer" />
               </>
             )}
          </div>
          <div className="space-y-4">
             <input placeholder="Full Name" className="w-full p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white font-black" value={customer.name} onChange={e => setCustomer({...customer, name: e.target.value})} />
             <input placeholder="NIK" className="w-full p-5 glass-card rounded-2xl border border-black/5 dark:border-white/5 dark:text-white font-black" value={customer.ktpNumber} onChange={e => setCustomer({...customer, ktpNumber: e.target.value})} />
          </div>
          <button onClick={() => setStep(5)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-sm">Next Step</button>
        </div>
      )}

      {step === 5 && (
        <div className="space-y-10">
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
             {['front', 'back', 'left', 'right', 'interior'].map(s => (
               <div key={s} className="relative aspect-square glass-card rounded-3xl border-2 border-dashed border-black/10 dark:border-white/10 flex flex-col items-center justify-center overflow-hidden transition-all hover:border-primary-500/30">
                  {photos[s] ? (
                    <img src={photos[s]} className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <Camera size={28} className="text-gray-400 mb-2"/>
                      <span className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest">{s}</span>
                    </>
                  )}
                  <input type="file" accept="image/*" onChange={e => {
                    const file = e.target.files?.[0];
                    if(file) {
                      const r = new FileReader();
                      r.onloadend = () => setPhotos({...photos, [s]: r.result as string});
                      r.readAsDataURL(file);
                    }
                  }} className="absolute inset-0 opacity-0 cursor-pointer" />
               </div>
             ))}
          </div>
          <button 
            disabled={Object.keys(photos).length < 5 || loading}
            onClick={handleSurvey}
            className="w-full py-7 bg-primary-500 text-white rounded-[3rem] font-black uppercase text-sm shadow-2xl flex items-center justify-center gap-4"
          >
            {loading ? <Loader2 className="animate-spin"/> : <Sparkles size={24}/>}
            {loading ? 'Analyzing...' : 'Run Neural Health Audit'}
          </button>
          {score && <div className="text-center p-6 bg-primary-500/10 rounded-2xl border border-primary-500/20">
             <p className="text-4xl font-black text-primary-500">{score.overall}%</p>
             <p className="text-xs font-black dark:text-white uppercase tracking-widest mt-2">Vehicle Health Integrity</p>
             <button onClick={() => setStep(6)} className="mt-6 px-10 py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-xs">Proceed to Payment</button>
          </div>}
        </div>
      )}

      {step === 6 && (
        <div className="space-y-10 animate-fade-in text-center py-20">
          <div className="w-32 h-32 bg-primary-500 text-white rounded-full flex items-center justify-center mx-auto mb-10 shadow-[0_0_50px_rgba(16,185,129,0.5)]">
            <CheckCircle2 size={64} strokeWidth={3}/>
          </div>
          <h2 className="text-5xl font-black uppercase dark:text-white tracking-tighter">Mission <span className="text-primary-500">Complete</span></h2>
          <p className="text-sm text-gray-500 font-bold uppercase tracking-widest px-12 leading-relaxed">Your neural protection layer has been deployed successfully.</p>
          <button onClick={onBack} className="px-16 py-6 bg-primary-500 text-white rounded-[3rem] font-black uppercase text-sm shadow-xl">Return to Hub</button>
        </div>
      )}
    </div>
  );
};

export default CarWizard;

